    image_patch = ImagePatch(image)
    food_patches = image_patch.find("food")
    table_patches = image_patch.find("table")

    if not food_patches:
        return image_patch
    if not table_patches:
        return food_patches[0]

    # Assuming the table is flat and the food is on it, we can find the food on the table
    table_top_depth = table_patches[0].compute_depth()
    on_table = [f for f in food_patches if f.compute_depth() <= table_top_depth]

    if on_table:
        return on_table[0]
    else:
        return food_patches[0]

modern_c4_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bowls = image_patch.find("bowl")
    tables = image_patch.find("table")

    if not bowls or not tables:
        return image_patch

    bowl_table_pairs = []
    for bowl in bowls:
        for table in tables:
            if is_on(bowl, table):
                bowl_table_pairs.append((bowl, table))

    if not bowl_table_pairs:
        return image_patch

    best_pair = max(bowl_table_pairs, key=lambda pair: pair[0].horizontal_center + pair[1].horizontal_center)

    return best_pair[0]


def is_on(item: ImagePatch, surface: ImagePatch) -> bool:
    item_bottom = item.upper
    surface_top = surface.lower
    return item_bottom <= surface_top

